+    quit(&mut harness);
+    let st = &harness.state().state;
+    assert!(st.unsaved_prompt.is_none() && st.request_quit, "a clean close never asks");
+}
+
+#[test]
+fn undo_back_to_the_saved_point_clears_the_mark() {
+    let mut harness = shell_harness();
